const GLYPHS      = Object.fromEntries(Object.entries(ECO).map(([k,v])=>[k,v.glyph]));
const ECO_BLURB  = Object.fromEntries(Object.entries(ECO).map(([k,v])=>[k,v.blurb]));
const ECO_PREFIX = Object.fromEntries(Object.entries(ECO).map(([k,v])=>[k,v.prefix]));

/* ───── Inject eco CSS selectors ───── */
(function(){
  const css = Object.entries(ECO).map(([eco,{prefix}])=>{
    if(eco === "Claude") return ""; /* Claude handled in styles.css */
    const v = `var(--eco-${prefix})`;
    return `.chip[data-eco="${eco}"][aria-pressed="true"]{box-shadow:inset 3px 0 0 ${v};}`
         + `.card[data-eco="${eco}"]{--eco-color:${v};}`
         + `.eco-cell[data-eco="${eco}"]{--eco-color:${v};}`;
  }).join("");
  const s = document.createElement("style");
  s.textContent = css;
  document.head.appendChild(s);
})();

